/**
 * Remark plugin: fills a fenced code block from a file at build time.
 *
 *   ```kotlin title="MyApplication.kt" file=<rootDir>/android-sdk/_snippets/init.kt
 *   ```
 *
 * The file's text becomes the block's value, so the code is part of the static HTML (and of the
 * Markdown copies and llms.txt that are derived from it). `<rootDir>` is the site root; a path
 * without it is resolved relative to the MDX file. The build fails when the file is missing.
 *
 * Generated by `npm run snippets:sync` from snippets.json; see scripts/syncSnippets.ts.
 */
const fs = require('fs');
const path = require('path');

function walk(node, visit) {
  visit(node);
  if (node.children) node.children.forEach((child) => walk(child, visit));
}

module.exports = function remarkSnippetFile(options = {}) {
  const rootDir = path.resolve(options.rootDir || process.cwd());

  return (tree, file) => {
    walk(tree, (node) => {
      if (node.type !== 'code' || !node.meta) return;
      const match = /(?:^|\s)file=(\S+)/.exec(node.meta);
      if (!match) return;

      const reference = match[1].replace('<rootDir>', rootDir);
      const base = file.dirname ? path.resolve(file.dirname) : rootDir;
      const absolute = path.resolve(base, reference);

      if (!absolute.startsWith(rootDir + path.sep)) {
        throw new Error(
          `Snippet path escapes the site root: ${match[1]} (in ${file.path})`
        );
      }
      if (!fs.existsSync(absolute)) {
        throw new Error(
          `Snippet file not found: ${match[1]} (in ${file.path}). Run "npm run snippets:sync".`
        );
      }

      node.value = fs.readFileSync(absolute, 'utf8').replace(/\s+$/, '');
      node.meta = node.meta.replace(match[0], '').trim() || null;
    });
  };
};
